#include <algorithm>

class Session {
public:
    bool start(fmi2String name, fmi2String guid, fmi2String resources,
               const fmi2CallbackFunctions *callbacks, fmi2Real startTime) {
        if (phase_ != Phase::Empty) return false;
        component_ = fmi2Instantiate(name, fmi2CoSimulation, guid, resources,
                                     callbacks, fmi2False, fmi2False);
        if (component_ == nullptr) return false;
        phase_ = Phase::Instantiated;

        if (!usable(fmi2SetupExperiment(component_, fmi2False, 0.0,
                                        startTime, fmi2False, 0.0))) return false;
        if (!usable(fmi2EnterInitializationMode(component_))) return false;
        phase_ = Phase::Initializing;
        if (!usable(fmi2ExitInitializationMode(component_))) return false;
        time_ = startTime;
        phase_ = Phase::Ready;
        return true;
    }

    bool advanceTo(fmi2Real target, fmi2Real maxStep,
                   fmi2ValueReference inputRef, fmi2Real inputValue,
                   fmi2ValueReference outputRef, fmi2Real *outputValue) {
        if (phase_ != Phase::Ready || target < time_ || maxStep <= 0.0) return false;
        if (!usable(fmi2SetReal(component_, &inputRef, 1, &inputValue))) return false;

        while (time_ < target) {
            fmi2Real step = std::min(maxStep, target - time_);
            if (!usable(fmi2DoStep(component_, time_, step, fmi2False))) return false;
            time_ += step;
        }
        return usable(fmi2GetReal(component_, &outputRef, 1, outputValue));
    }

    void close() {
        if (component_ == nullptr) return;
        if (phase_ == Phase::Ready) (void)fmi2Terminate(component_);
        fmi2FreeInstance(component_);
        component_ = nullptr;
        phase_ = Phase::Closed;
    }

private:
    enum class Phase { Empty, Instantiated, Initializing, Ready, Closed };
    static bool usable(fmi2Status status) {
        return status == fmi2OK || status == fmi2Warning;
    }

    fmi2Component component_ = nullptr;
    fmi2Real time_ = 0.0;
    Phase phase_ = Phase::Empty;
};
